'use strict';
const toggle=document.querySelector('.menu-toggle');
const menu=document.getElementById('all-menu');
function closeMenu(){if(!toggle||!menu)return;menu.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','전체 메뉴 열기');}
toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'전체 메뉴 닫기':'전체 메뉴 열기');menu.hidden=!open;});
document.addEventListener('click',e=>{if(!e.target.closest('.site-header'))closeMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu?.hidden){closeMenu();toggle?.focus();}});
const filters=[...document.querySelectorAll('[data-filter]')];
const cards=[...document.querySelectorAll('.project-card')];
const tableRows=[...document.querySelectorAll('.project-table tbody tr')];
filters.forEach(button=>button.addEventListener('click',()=>{const category=button.dataset.filter;let count=0;filters.forEach(b=>{const selected=b===button;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});cards.forEach(c=>{const visible=category==='전체'||c.dataset.category===category;c.hidden=!visible;if(visible)count++;});tableRows.forEach(row=>{row.hidden=category!=='전체'&&row.dataset.category!==category;});const counter=document.querySelector('.filter-count');if(counter)counter.textContent=`${category==='전체'?'연도별 실적':category} ${count}건`;const empty=document.querySelector('.empty-projects');if(empty)empty.hidden=count!==0;}));
const viewButtons=[...document.querySelectorAll('[data-view]')];
viewButtons.forEach(button=>button.addEventListener('click',()=>{const isTable=button.dataset.view==='table';document.querySelector('.project-grid').hidden=isTable;document.querySelector('.project-table-wrap').hidden=!isTable;viewButtons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));
const dialog=document.getElementById('project-dialog');
const projectData=document.getElementById('project-data');
let lastProjectTrigger;
if(dialog&&projectData){const projects=JSON.parse(projectData.textContent);document.querySelectorAll('[data-project]').forEach(trigger=>trigger.addEventListener('click',()=>{const p=projects[Number(trigger.dataset.project)];if(!p)return;lastProjectTrigger=trigger;const content=document.getElementById('project-detail');content.replaceChildren();const meta=document.createElement('p');meta.textContent=`${p.category} · ${p.year}${p.status?' · '+p.status:''}`;const title=document.createElement('h2');title.id='project-modal-title';title.textContent=p.title;content.append(meta,title);if(p.image){const image=document.createElement('img');image.src='/assets/'+(p.imageFallback||p.image);if(p.imageSrcset){image.srcset=p.imageSrcset;image.sizes='(max-width:700px) calc(100vw - 86px), 574px';image.width=p.imageWidth;image.height=p.imageHeight;}image.decoding='async';if(p.imageWidth/p.imageHeight>2.8)image.style.objectFit='contain';image.alt=p.photoCaption||p.title+' 건축물 전경';image.className='modal-project-photo';const caption=document.createElement('p');caption.className='modal-photo-caption';caption.textContent=p.photoCaption||'대상 건축물 외관';content.append(image,caption);}const dl=document.createElement('dl');const details=[['발주처',p.client],['공사금액',p.amount],['금액 기준',p.amountBasis||'기존 공개 실적 기준'],['공사내용',p.scope]];if(p.period)details.push(['공사기간',p.period]);details.forEach(([label,value])=>{const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;row.append(dt,dd);dl.append(row);});content.append(dl);if(p.sourceUrl){const source=document.createElement('a');source.href=p.sourceUrl;source.target='_blank';source.rel='noopener noreferrer';source.className='project-record-source';source.textContent='공개 실적 기록 보기 ↗';content.append(source);}const link=document.createElement('a');link.href='/contact/';link.className='button yellow';link.textContent='비슷한 공사 상담하기 →';content.append(link);dialog.setAttribute('aria-labelledby','project-modal-title');dialog.showModal();document.body.classList.add('body-dialog-open');}));dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{document.body.classList.remove('body-dialog-open');lastProjectTrigger?.focus();});}
const form=document.getElementById('contact-form');
if(form){const status=document.getElementById('form-status');const compose=()=>{const d=new FormData(form);return {subject:`[KJS 홈페이지 문의] ${d.get('type')} / ${d.get('name')}`,body:`문의 분야: ${d.get('type')}\n이름: ${d.get('name')}\n연락처: ${d.get('phone')}\n이메일: ${d.get('email')||'미입력'}\n\n[문의내용]\n${d.get('message')}\n\n개인정보 수집 및 이용 동의: 동의`};};form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const c=compose();window.location.href=`mailto:info@kjs-elec.kr?subject=${encodeURIComponent(c.subject)}&body=${encodeURIComponent(c.body)}`;status.textContent='메일 앱에서 전송을 완료해 주세요. 메일 앱이 열리지 않으면 문의내용을 복사해 info@kjs-elec.kr으로 보내주세요.';});form.querySelector('.copy-inquiry').addEventListener('click',async()=>{if(!form.reportValidity())return;const c=compose(),text=c.subject+'\n\n'+c.body;try{await navigator.clipboard.writeText(text);status.textContent='문의내용을 복사했습니다. info@kjs-elec.kr으로 보내주세요.';}catch{const field=document.createElement('textarea');field.value=text;field.setAttribute('aria-label','복사할 문의내용');form.append(field);field.focus();field.select();status.textContent='자동 복사가 지원되지 않습니다. 아래 선택된 내용을 복사해 이메일로 보내주세요.';}});}

if(form){form.querySelector('button[type="submit"]').disabled=false;}
